package com.anaiv.fluxogestao.repository;
import com.anaiv.fluxogestao.entity.*; import org.springframework.data.jpa.repository.JpaRepository; import org.springframework.data.jpa.repository.Query; import java.util.*;
public interface OrdemServicoPortoRepository extends JpaRepository<OrdemServicoPorto,Long>{Optional<OrdemServicoPorto> findByNumero(String numero);List<OrdemServicoPorto> findByNumeroIn(Collection<String> numeros);List<OrdemServicoPorto> findByOrdemPagamento(OrdemPagamentoPorto op);List<OrdemServicoPorto> findByImportacao(Importacao importacao);List<OrdemServicoPorto> findByMotorista(Motorista motorista);@Query("select distinct os from OrdemServicoPorto os left join fetch os.ordemPagamento op left join fetch op.calendarioPagamento left join fetch op.importacao left join fetch os.motorista left join fetch os.importacao")List<OrdemServicoPorto> findAllParaListagem();}
